import { resolveConfig } from '@projexlight/sdk-config';

const row = await resolveConfig('payment.provider', {
  tenant_id: req.auth.tenant_id,
  app_id: req.auth.app_id,
  app_user_id: req.auth.sub,
});
// row?.scope tells you WHICH level won: 'app_user' | 'app' | 'tenant' | 'platform'
const provider = row?.value?.provider ?? null;

import { setConfig, checkProviderConfigured } from '@projexlight/sdk-config';

await setConfig({ scope: 'tenant', scope_id: tenantId, key: 'payment.provider', value: { provider: 'stripe' }, set_by: userId });

// in the route handler:
const notConfigured = await checkProviderConfigured('payment.provider', ctxFrom(req));
if (notConfigured) return reply.code(503).send(notConfigured);

import { setConfig, rotateConfigSecret } from '@projexlight/sdk-config';

await setConfig({ scope: 'tenant', scope_id: tenantId, key: 'email.provider.apiKey', secret_ref: 'secret://tenant/email-key-v1', set_by: userId });

// later, rotate to a new envelope pointer atomically:
await rotateConfigSecret('tenant', tenantId, 'email.provider.apiKey', 'secret://tenant/email-key-v2', userId);
